// ═══════════════════════════════════════════════════════════════════════
//  THE ONLY NODE YOU EDIT. One { … } block per scheduled briefing.
// ═══════════════════════════════════════════════════════════════════════
//
//  ⚠️ EACH FIRING COSTS ONE AGENTIC TURN. That is intended here — you are
//     asking an agent to actually go and do work — but it is why this list
//     should hold briefings, not watchers. Anything of the form "check if X
//     happened" belongs in mail_watch / web_publish_watch instead, where the
//     check is free and only a real hit costs anything.
//
//  id       REQUIRED, stable. Used to remember "already fired today".
//  at       REQUIRED, 'HH:MM' in the timezone below.
//  days     '*' or weekday numbers, 1=Mon … 7=Sun. E.g. '1,2,3,4,5' or '7'.
//  on       'YYYY-MM-DD' for a ONE-SHOT that fires on that date only, then
//           never again. Delete the entry afterwards; leaving it is harmless.
//  dom      Day of month, '1'..'31', for monthly runs. Ignored when `on` is set.
//  agent    Who runs it, in whose voice it arrives. Default 'speda'.
//  intent   REQUIRED. What the agent should DO — written as an instruction to
//           itself. Be specific about which tools to use; a vague intent gets
//           a vague briefing.
//  mode     'push' (delivered to Telegram, the default) or 'silent' (runs and
//           is stored, nothing is sent — good for indexing or bookkeeping).
//
const TZ = 'Europe/Istanbul';

const BRIEFINGS = [

  {
    id: 'morning_brief',
    at: '08:00',
    days: '*',
    agent: 'speda',
    mode: 'push',
    intent: "GUNLUK SABAH BRIEFINGI — bu bir is akisidir, GERCEK araclarla calistir. Su adimlari sirayla yap ve owner a kisa, oz, Turkce bir sabah briefingi yaz (yazdigin metin owner a otomatik push olarak iletilir — send_telegram_message CAGIRMA):\n\n1. ONEMLI MAILLER — use_toolset ile google_gmail i yukle, sonra son 24 saatteki onemli mailleri gercek verilerle ozetle (spam/bulten haric). Onemli mail yoksa \"yeni onemli mail yok\" yaz.\n2. TAKVIM — use_toolset ile google_calendar i yukle, bugunun etkinliklerini ve onumuzdeki 3 gundeki onemli etkinlikleri listele. Bossa oyle belirt.\n3. ONEMLI HABERLER — news_deep_dive ile Turkiye ve kategoriler bazinda (country='tr') son 24 saatin one cikan 3-5 haberini kisa ver. category secerek (politics, business, technology) farkli alanlari temsil et.\n4. SERVER DURUMU — system_info (metric=all) ile disk, bellek ve uptime i GERCEK degerlerle raporla; anormal bir sey varsa vurgula.\n\nHicbir veriyi UYDURMA. Bir arac hata verir veya bos donerse bunu durustce yaz. Baslik: \"Gunluk Briefing — [bugunun tarihi]\".",
  },

  {
    id: 'atomix_health',
    at: '08:00',
    days: '*',
    agent: 'atomix',
    mode: 'push',
    intent: "DAILY HEALTH BRIEFING — bu bir iş akışıdır, GERÇEK araçlarla çalıştır. health_data aracını kullanarak şu metrikleri çek (range: 'today' veya bugüne denk gelen en son gece):\n\n1. UYKU (sleep_session) — Dün geceki uyku: toplam süre, başlangıç-bitiş saati, stage breakdown (deep, REM, light, awake). Deep ve REM sürelerini ve oranlarını özellikle belirt.\n2. NABIZ (heart_rate + resting_heart_rate) — Uyku saatleri boyunca ortalama nabız, minimum nabız (en düşük gece nabzı), ve sabah resting heart rate. Önceki günlerle karşılaştır (range parametresini '7d' vererek trend alabilirsin).\n3. DEĞERLENDİRME — Deep sleep ≥ 1h 20m ve REM ≥ 1h 20m iyi; altındaysa uyar. Gece nabzı önceki günlere göre yükselmişse recovery bozukluğu sinyali. RHR 50-60 arası iyi, 60+ yorgunluk göstergesi. Sleep data yoksa 'gece uyku verisi alınamadı — saat kontrol et' yaz.\n4. ADIM (steps) — Dünkü toplam adım, hedef 8-12k'ya göre durum.\n\nFormat: kısa, öz, Türkçe. Başlık: 'Sağlık Briefingi — [tarih]'. Her veri GERÇEK health_data çıktısından gelmeli — UYDURMA. Veri yoksa durumu dürüstçe yaz. Yazdığın metin owner'a otomatik push olarak iletilir — send_telegram_message ÇAĞIRMA.",
  },

  {
    id: 'atomix_evening',
    at: '23:00',
    // 23:00, not 20:00. The old standalone workflow's cron said '0 20', but
    // n8n was reading it as UTC, so it had always fired at 23:00 Istanbul —
    // and 23:00 is the time the owner actually wants. Fixing the timezone
    // silently moved it three hours earlier; this puts it back.
    days: '*',
    agent: 'atomix',
    // 'silent' because the reminders tool does the delivering, with answer
    // buttons attached. On 'push' the reply would ALSO be pushed and the
    // owner would get the same checklist twice, once unanswerable.
    mode: 'silent',
    intent: "EVENING REMINDER — bu Atomix'in kişisel hatırlatmasıdır ve owner'ın ONAYLAMASI gerekir.\n\nÖnce mesajı yaz: owner'a sanki Atomix yazmış gibi, kısa ve doğal bir Türkçe mesaj. İçeriği statik metin olarak yazma; günün durumuna göre kişiselleştir. Şunları hatırlat:\n\n1. 150 mg Lustral al\n2. 5 g kreatin al\n3. Spor salonu giriş kartını al\n4. Yarınki antrenman için spor çantanı hazırla\n\nEğer bugün gym günü ise (Pazartesi/Çarşamba/Cuma) 'bugün antrenman yaptın, yarın dinlenme günü' notunu ekle. Eğer yarın gym günü ise 'yarın gym günü, çantanı hazırla' vurgusunu güçlendir. Hafta sonu ise daha rahat bir ton kullan. Mesajı Atomix'in sesiyle yaz — doğal, kısa, ilgilendiğini gösteren.\n\nSONRA — ve bu kritik — mesajı `reminders` aracıyla gönder:\n  action='ask', reminder_id='atomix_evening', text=<yazdığın mesaj>,\n  options=['✅ Hepsini yaptım', '⏭️ Bugün atlıyorum'],\n  every_minutes=5, max_asks=10\n\nBu araç mesajı butonlarla gönderir ve owner cevaplayana kadar 5 dakikada bir TEKRAR sorar. İlaç hatırlatması bu yüzden var: kaçırılmamalı. send_telegram_message ÇAĞIRMA ve mesajı sadece cevap olarak yazma — tek gönderim yolu bu araçtır. Araç 'already_open' derse ikinci bir mesaj gönderme, zaten bekliyor demektir.",
  },

  {
    id: 'gym_renewal',
    at: '08:00',
    on: '2026-07-29',       // one-shot: fires on this date only
    agent: 'sentinel',
    mode: 'push',
    intent: "GYM RENEWAL REMINDER. Today is July 29 — the owner's gym membership renewal day. Send a concise push notification reminding him: 'Gym membership yenileme günü — bugün 29 Temmuz. Yenileme işlemini tamamla.' Your reply auto-delivers as a push to the owner — do NOT call send_telegram_message. Keep it short.",
  },

  // Was inactive as a standalone workflow — uncomment to switch it on.
  // { id: 'monthly_finance', at: '09:00', dom: '1', agent: 'sentinel', mode: 'push',
  //   intent: "Remind Ahmet to provide current month's expenses and income data for finance review and logging. Ask for specific amounts and categorize them properly for the finance records." },

];

// ── Nothing below this line needs editing ───────────────────────────────
// "Already fired today" lives in the workflow's static data, so a briefing
// fires ONCE at its time rather than on every tick for the rest of the day.
const store = $getWorkflowStaticData('global');
const fired = store.fired || {};
// How late a briefing's FIRST-EVER firing may be. A briefing this list has
// never seen before is only run if it came due within this window; one that
// went by hours ago is recorded as done instead. That covers both cases that
// would otherwise fire a stale briefing on the spot: activating the workflow
// in the afternoon, and adding a new 08:00 entry to a running one.
const GRACE_MIN = 15;

// Read the clock in the configured zone explicitly rather than trusting the
// container's TZ — that assumption is exactly what made every schedule in this
// system three hours out.
const parts = new Intl.DateTimeFormat('en-GB', {
  timeZone: TZ, hour12: false,
  year: 'numeric', month: '2-digit', day: '2-digit',
  hour: '2-digit', minute: '2-digit', weekday: 'short',
}).formatToParts(new Date()).reduce((a, p) => (a[p.type] = p.value, a), {});

const today = `${parts.year}-${parts.month}-${parts.day}`;
const nowMin = Number(parts.hour) * 60 + Number(parts.minute);
const dowNum = { Mon: 1, Tue: 2, Wed: 3, Thu: 4, Fri: 5, Sat: 6, Sun: 7 }[parts.weekday];

const out = [];
BRIEFINGS.forEach(b => {
  if (!b || !b.id || !b.at || !b.intent) { return; }
  if (fired[b.id] === today) { return; }                       // already ran today
  if (b.on) {
    if (today !== String(b.on)) { return; }                   // one-shot, wrong day
  } else {
    if (b.dom && Number(b.dom) !== Number(parts.day)) { return; }        // monthly
    const days = String(b.days || '*');
    if (days !== '*' && !days.split(',').map(s => s.trim()).includes(String(dowNum))) { return; }
  }
  const [hh, mm] = String(b.at).split(':').map(Number);
  const dueMin = hh * 60 + mm;
  if (nowMin < dueMin) { return; }                             // not yet

  const firstSight = fired[b.id] === undefined;
  fired[b.id] = today;
  if (firstSight && nowMin - dueMin > GRACE_MIN) { return; }   // seed, don't retro-fire
  out.push({ json: {
    id: b.id,
    agent: (b.agent || 'speda').trim(),
    intent: b.intent,
    mode: b.mode === 'silent' ? 'silent' : 'push',
    at: b.at,
  }, pairedItem: { item: 0 } });
});

store.fired = fired;
return out;
